<!-- wp:group {"tagName":"section","anchor":"ist-nicht","align":"full","style":{"spacing":{"padding":{"top":"var:preset|spacing|section","bottom":"var:preset|spacing|section"},"blockGap":"var:preset|spacing|10"}},"layout":{"type":"constrained","contentSize":"72rem"}} -->
<section id="ist-nicht" class="wp-block-group alignfull" style="padding-top:var(--wp--preset--spacing--section);padding-bottom:var(--wp--preset--spacing--section)">
	<!-- wp:group {"style":{"spacing":{"blockGap":"var:preset|spacing|3"}},"layout":{"type":"default"}} -->
	<div class="wp-block-group">
		<!-- wp:paragraph {"className":"is-style-eyebrow"} -->
		<p class="is-style-eyebrow">Was sie nicht ist</p>
		<!-- /wp:paragraph -->

		<!-- wp:heading -->
		<h2 class="wp-block-heading">Vier verbreitete Missverständnisse</h2>
		<!-- /wp:heading -->

		<!-- wp:paragraph -->
		<p>Wo Erwartungen und Forschungsstand auseinandergehen.</p>
		<!-- /wp:paragraph -->
	</div>
	<!-- /wp:group -->

	<!-- wp:group {"style":{"spacing":{"blockGap":"var:preset|spacing|6"}},"layout":{"type":"grid","columnCount":2,"minimumColumnWidth":"20rem"}} -->
	<div class="wp-block-group">
		<!-- wp:group {"className":"is-style-card","style":{"spacing":{"blockGap":"var:preset|spacing|4"}},"layout":{"type":"default"}} -->
		<div class="wp-block-group is-style-card">
			<!-- wp:bw/icon {"icon":"x-circle","tone":"red"} /-->

			<!-- wp:heading {"level":3} -->
			<h3 class="wp-block-heading">Kein „Denk doch positiv!“</h3>
			<!-- /wp:heading -->

			<!-- wp:paragraph -->
			<p>Toxische Positivität wertet Trauer, Angst oder Wut ab und lässt Betroffene mit ihren Gefühlen allein. Positive Psychologie schließt Belastungen ausdrücklich ein, denn Wohlbefinden braucht auch schwierige Gefühle.</p>
			<!-- /wp:paragraph -->
		</div>
		<!-- /wp:group -->

		<!-- wp:group {"className":"is-style-card","style":{"spacing":{"blockGap":"var:preset|spacing|4"}},"layout":{"type":"default"}} -->
		<div class="wp-block-group is-style-card">
			<!-- wp:bw/icon {"icon":"x-circle","tone":"red"} /-->

			<!-- wp:heading {"level":3} -->
			<h3 class="wp-block-heading">Kein Ersatz für Psychotherapie</h3>
			<!-- /wp:heading -->

			<!-- wp:paragraph -->
			<p>Bei Depression, Trauma oder Angststörungen braucht es fachliche Behandlung. Die Effekte von Übungen sind oft klein bis moderat: In einer Schülerstudie stieg das Wohlbefinden, depressive Symptome blieben jedoch unverändert.</p>
			<!-- /wp:paragraph -->
		</div>
		<!-- /wp:group -->

		<!-- wp:group {"className":"is-style-card","style":{"spacing":{"blockGap":"var:preset|spacing|4"}},"layout":{"type":"default"}} -->
		<div class="wp-block-group is-style-card">
			<!-- wp:bw/icon {"icon":"x-circle","tone":"red"} /-->

			<!-- wp:heading {"level":3} -->
			<h3 class="wp-block-heading">Keine Zauberformeln</h3>
			<!-- /wp:heading -->

			<!-- wp:paragraph -->
			<p>Beispiel Positivitätsrate: Das Verhältnis 2,9013 zu 1 galt als „Erfolgsformel“. 2013 wiesen Brown, Sokal und Friedman nach, dass die zugrunde liegende Mathematik haltlos ist, die Autor:innen zogen sie zurück. Ein Lehrstück für sorgfältige Prüfung.</p>
			<!-- /wp:paragraph -->
		</div>
		<!-- /wp:group -->

		<!-- wp:group {"className":"is-style-card","style":{"spacing":{"blockGap":"var:preset|spacing|4"}},"layout":{"type":"default"}} -->
		<div class="wp-block-group is-style-card">
			<!-- wp:bw/icon {"icon":"x-circle","tone":"red"} /-->

			<!-- wp:heading {"level":3} -->
			<h3 class="wp-block-heading">Keine Pflicht zur Selbstoptimierung</h3>
			<!-- /wp:heading -->

			<!-- wp:paragraph -->
			<p>Wohlbefinden hängt auch von Arbeit, Bildung und Teilhabe ab, nicht nur von der inneren Haltung. Wer ständig „gut drauf“ sein soll, fühlt sich schnell schuldig. Gute Anwendung verändert deshalb auch Bedingungen, nicht nur Menschen.</p>
			<!-- /wp:paragraph -->
		</div>
		<!-- /wp:group -->
	</div>
	<!-- /wp:group -->
</section>
<!-- /wp:group -->

